<?php $roleLabels=['administrator'=>'Acceso administrativo','teacher'=>'Docente','student'=>'Estudiante'];?>
<main class="profile-shell"><nav><a href="<?=e(route('dashboard'))?>">Inicio</a><i class="fa-solid fa-chevron-right"></i><span>Mi perfil</span></nav><header class="profile-header"><span><?=e(mb_strtoupper(mb_substr($profile['full_name'],0,1,'UTF-8'),'UTF-8'))?></span><div><small>Cuenta institucional</small><h1><?=e($profile['full_name'])?></h1><p><?=e($profile['email'])?></p></div></header><div class="profile-grid"><section><h2>Información personal</h2><p>Confirma tu contraseña actual para guardar cambios.</p><?php if($profileError):?><div class="profile-message error" role="alert"><?=e($profileError)?></div><?php endif;?><?php if($profileSuccess):?><div class="profile-message success" role="status"><?=e($profileSuccess)?></div><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?=e($profileCsrf)?>"><label>Nombre completo<input name="full_name" value="<?=e($profile['full_name'])?>" maxlength="180" required></label><label>Correo<input type="email" name="email" value="<?=e($profile['email'])?>" maxlength="190" required></label><label>Contraseña actual<input type="password" name="current_password" autocomplete="current-password" required></label><button type="submit">Guardar cambios</button></form></section><aside><h2>Resumen de la cuenta</h2><dl><div><dt>Rol</dt><dd><?=e(implode(', ',array_map(fn($role)=>$roleLabels[$role]??$role,$profile['roles'])))?></dd></div><div><dt>Cuenta creada</dt><dd><?=$profile['created_at']?e(date('d/m/Y',strtotime($profile['created_at']))):'No disponible'?></dd></div><div><dt>Último acceso</dt><dd><?=$profile['last_login_at']?e(date('d/m/Y H:i',strtotime($profile['last_login_at']))):'Primer acceso'?></dd></div><div><dt>Contraseña actualizada</dt><dd><?=$profile['password_changed_at']?e(date('d/m/Y',strtotime($profile['password_changed_at']))):'Pendiente'?></dd></div></dl><a href="<?=e(route('change-password'))?>"><i class="fa-solid fa-key"></i> Cambiar contraseña</a></aside></div></main>
